/// `ctxloom.v1`.
pub use ctxloom::v1;

/// The response metadata key the daemon's standing warnings ride on (owner
/// ruling OD-55): every answer of its `Ctxloom` service, a refusal's status
/// too, carries one value per warning, each a prost-encoded [`v1::Notice`]
/// (its code and args, so the client renders it from its own catalog). A
/// `-bin` key: gRPC's binary metadata, base64 on the wire, the key repeated
/// for a list.
pub const WARNING_METADATA: &str = "ctxloom-warning-bin";

/// The response metadata key a library read's own notices ride on (step 10a
/// U2, owner ruling 2026-11-17): every answer of a library Get, List or
/// Search (`library_reads!`) carries one value per notice the read said (its
/// observation's, `library-api-notice-tree-in-motion` and
/// `-home-repository-made`, and the library's own), each a prost-encoded
/// [`v1::Notice`], encoded as [`WARNING_METADATA`]'s are. Kept apart from
/// the standing warnings: a notice is this call's, a warning the daemon's.
/// AIP-131 has a Get answer its resource alone, so no message carries them.
pub const NOTICE_METADATA: &str = "ctxloom-notice-bin";

/// The library's reads (step 10a U2, D12): ONE table of the service's
/// library Get, List and Search methods, which every layer they cross
/// generates its part from, so a read is added in one line. Each row is
/// `snake (Pascal) Request.target => Response`, the target the field that
/// names what is read (a Get's `name`, a List's or a Search's `parent`);
/// `$each` is the caller's macro, handed the whole table:
///
/// ```ignore
/// macro_rules! port { ($($m:ident ($n:ident) $q:ident . $t:ident => $r:ident),* $(,)?) => { ... } }
/// daemon_proto::library_reads!(port);
/// ```
///
/// The layers: `daemon-ports`' `DaemonApi` (a default that answers the
/// method unserved), `daemon-client`'s call, `daemon-api`'s `Calls` (each
/// a library read observed first, then answered by `library-api`) and
/// `daemon-api-grpc`'s handler.
#[macro_export]
macro_rules! library_reads {
    ($each:ident) => {
        $each! {
            get_bundle (GetBundle) GetBundleRequest.name => Bundle,
            list_bundles (ListBundles) ListBundlesRequest.parent => ListBundlesResponse,
            get_fragment (GetFragment) GetFragmentRequest.name => Fragment,
            list_fragments (ListFragments) ListFragmentsRequest.parent => ListFragmentsResponse,
            get_command (GetCommand) GetCommandRequest.name => Command,
            list_commands (ListCommands) ListCommandsRequest.parent => ListCommandsResponse,
            get_premise_index (GetPremiseIndex) GetPremiseIndexRequest.name => PremiseIndex,
            get_skill (GetSkill) GetSkillRequest.name => Skill,
            list_skills (ListSkills) ListSkillsRequest.parent => ListSkillsResponse,
            get_mcp_server (GetMcpServer) GetMcpServerRequest.name => McpServer,
            list_mcp_servers (ListMcpServers) ListMcpServersRequest.parent => ListMcpServersResponse,
            get_profile (GetProfile) GetProfileRequest.name => Profile,
            list_profiles (ListProfiles) ListProfilesRequest.parent => ListProfilesResponse,
            get_agent (GetAgent) GetAgentRequest.name => Agent,
            list_agents (ListAgents) ListAgentsRequest.parent => ListAgentsResponse,
            get_engine (GetEngine) GetEngineRequest.name => Engine,
            list_engines (ListEngines) ListEnginesRequest.parent => ListEnginesResponse,
            list_companions (ListCompanions) ListCompanionsRequest.parent => ListCompanionsResponse,
            get_remote (GetRemote) GetRemoteRequest.name => Remote,
            browse_remote (BrowseRemote) BrowseRemoteRequest.name => BrowseRemoteResponse,
            list_remotes (ListRemotes) ListRemotesRequest.parent => ListRemotesResponse,
            list_dependencies (ListDependencies) ListDependenciesRequest.parent => ListDependenciesResponse,
            get_config (GetConfig) GetConfigRequest.name => Config,
            search_library (SearchLibrary) SearchLibraryRequest.parent => SearchLibraryResponse,
            get_loadout (GetLoadout) GetLoadoutRequest.name => Loadout,
        }
    };
}

/// The library's writes the daemon serves (step 10b U3, D12), one row
/// each: `method (Rpc) Request => Response` (what each request writes,
/// its target, is `daemon-api`'s `LibraryWriteRequest`). The same layers as
/// [`library_reads!`]'s generate their part from it; a write's notices ride
/// in its response's own `notices`.
#[macro_export]
macro_rules! library_writes {
    ($each:ident) => {
        $each! {
            create_bundle (CreateBundle) CreateBundleRequest => CreateBundleResponse,
            update_bundle (UpdateBundle) UpdateBundleRequest => UpdateBundleResponse,
            create_fragment (CreateFragment) CreateFragmentRequest => CreateFragmentResponse,
            update_fragment (UpdateFragment) UpdateFragmentRequest => UpdateFragmentResponse,
            create_command (CreateCommand) CreateCommandRequest => CreateCommandResponse,
            update_command (UpdateCommand) UpdateCommandRequest => UpdateCommandResponse,
            update_config (UpdateConfig) UpdateConfigRequest => UpdateConfigResponse,
            edit_config (EditConfig) EditConfigRequest => EditConfigResponse,
            create_skill (CreateSkill) CreateSkillRequest => CreateSkillResponse,
            update_mcp_server (UpdateMcpServer) UpdateMcpServerRequest => UpdateMcpServerResponse,
            create_profile (CreateProfile) CreateProfileRequest => CreateProfileResponse,
            update_profile (UpdateProfile) UpdateProfileRequest => UpdateProfileResponse,
            create_companion (CreateCompanion) CreateCompanionRequest => CreateCompanionResponse,
            enable_companion (EnableCompanion) EnableCompanionRequest => EnableCompanionResponse,
            disable_companion (DisableCompanion) DisableCompanionRequest => DisableCompanionResponse,
            set_default_agent (SetDefaultAgent) SetDefaultAgentRequest => SetDefaultAgentResponse,
            create_agent (CreateAgent) CreateAgentRequest => CreateAgentResponse,
            update_agent (UpdateAgent) UpdateAgentRequest => UpdateAgentResponse,
            export_bundle (ExportBundle) ExportBundleRequest => ExportBundleResponse,
            move_bundle (MoveBundle) MoveBundleRequest => MoveBundleResponse,
            import_bundle (ImportBundle) ImportBundleRequest => ImportBundleResponse,
            delete_bundle (DeleteBundle) DeleteBundleRequest => DeleteBundleResponse,
            delete_fragment (DeleteFragment) DeleteFragmentRequest => DeleteFragmentResponse,
            delete_command (DeleteCommand) DeleteCommandRequest => DeleteCommandResponse,
            delete_skill (DeleteSkill) DeleteSkillRequest => DeleteSkillResponse,
            delete_profile (DeleteProfile) DeleteProfileRequest => DeleteProfileResponse,
            delete_agent (DeleteAgent) DeleteAgentRequest => DeleteAgentResponse,
            delete_companion (DeleteCompanion) DeleteCompanionRequest => DeleteCompanionResponse,
            clean (Clean) CleanRequest => CleanResponse,
            materialize (Materialize) MaterializeRequest => MaterializeResponse,
            uninstall_manage (UninstallManage) UninstallManageRequest => UninstallManageResponse,
            run_doctor (RunDoctor) RunDoctorRequest => RunDoctorResponse,
            get_auth_status (GetAuthStatus) GetAuthStatusRequest => GetAuthStatusResponse,
            check_manage (CheckManage) CheckManageRequest => CheckManageResponse,
            get_init_prompt (GetInitPrompt) GetInitPromptRequest => GetInitPromptResponse,
            install_gitignore (InstallGitignore) InstallGitignoreRequest => InstallGitignoreResponse,
            init_project (InitProject) InitProjectRequest => InitProjectResponse,
            install_manage (InstallManage) InstallManageRequest => InstallManageResponse,
            distill_fragment (DistillFragment) DistillFragmentRequest => DistillFragmentResponse,
            distill_command (DistillCommand) DistillCommandRequest => DistillCommandResponse,
            create_remote (CreateRemote) CreateRemoteRequest => CreateRemoteResponse,
            update_remote (UpdateRemote) UpdateRemoteRequest => UpdateRemoteResponse,
            delete_remote (DeleteRemote) DeleteRemoteRequest => DeleteRemoteResponse,
            set_default_remote (SetDefaultRemote) SetDefaultRemoteRequest => SetDefaultRemoteResponse,
            pull_dependencies (PullDependencies) PullDependenciesRequest => PullDependenciesResponse,
            upgrade_dependencies (UpgradeDependencies) UpgradeDependenciesRequest => UpgradeDependenciesResponse,
        }
    };
}

/// What a message carries of its client (owner, 2026-11-18): every request
/// made on a user's behalf carries one [`v1::Caller`] at field 98 (its
/// directory, its whole environment, its global flags, what it can present
/// of a need, and which client it is). Implemented for every top-level
/// message of the package, generated from the protos: `CALLER` says whether
/// the message has the field. The daemon's edge admits a request that
/// carries it only from a client of its own version.
pub trait Carries {
    /// Whether the message has a `caller` field.
    const CALLER: bool;
    /// Its `caller`; none when it carries none, or has no such field.
    fn caller(&self) -> Option<&v1::Caller>;
    /// Its `caller` field, to be written; none when it has no such field.
    fn caller_field(&mut self) -> Option<&mut Option<v1::Caller>>;
    /// The message, carrying what `filled` says that its own caller does
    /// not ([`v1::Caller::fill_from`]); a message with no `caller` field is
    /// left as it is (owner, 2026-11-18: the transport fills every request
    /// made on a user's behalf).
    fn fill_caller_from(&mut self, filled: &v1::Caller) {
        if let Some(field) = self.caller_field() {
            field
                .get_or_insert_with(v1::Caller::default)
                .fill_from(filled);
        }
    }
    /// The caller's whole environment.
    fn caller_env(&self) -> Option<&v1::EnvVars> {
        self.caller().and_then(|caller| caller.env.as_ref())
    }
    /// The global flags the call is planned under.
    fn caller_globals(&self) -> Option<&v1::Globals> {
        self.caller().and_then(|caller| caller.globals.as_ref())
    }
    /// The caller's working directory; empty, the project's registered root.
    fn caller_cwd(&self) -> &str {
        self.caller().map_or("", |caller| caller.cwd.as_str())
    }
    /// What the caller can present of a need.
    fn caller_presentable(&self) -> Option<&v1::Presentable> {
        self.caller().and_then(|caller| caller.presentable.as_ref())
    }
    /// Which client asked.
    fn caller_client(&self) -> Option<&v1::Client> {
        self.caller().and_then(|caller| caller.client.as_ref())
    }
}

/// A message with a `caller` field, written: what a client fills.
pub trait CarriesMut: Carries {
    /// The field itself.
    fn caller_slot(&mut self) -> &mut Option<v1::Caller>;
    /// Its `caller`, made empty where it had none.
    fn caller_mut(&mut self) -> &mut v1::Caller {
        self.caller_slot().get_or_insert_with(v1::Caller::default)
    }
    /// The message, carrying `env` as its caller's environment.
    fn set_caller_env(&mut self, env: v1::EnvVars) {
        self.caller_mut().env = Some(env);
    }
    /// The message, at the caller's working directory `cwd`.
    fn set_caller_cwd(&mut self, cwd: String) {
        self.caller_mut().cwd = cwd;
    }
    /// What `filled` says that the message's own caller does not: its
    /// directory, environment, flags, presentable and client, each where the
    /// message names none (a command sets its own flags and presentable; the
    /// client the rest).
    fn fill_caller(&mut self, filled: &v1::Caller) {
        self.caller_mut().fill_from(filled);
    }
}

impl v1::Caller {
    /// A command's own part of its caller: the global flags it is planned
    /// under and what it can present of a need. The client it runs in fills
    /// the rest ([`CarriesMut::fill_caller`]).
    pub fn of(
        globals: Option<v1::Globals>,
        presentable: Option<v1::Presentable>,
    ) -> Option<v1::Caller> {
        Some(v1::Caller {
            globals,
            presentable,
            ..v1::Caller::default()
        })
    }

    /// This caller, with what `filled` says that it does not: its
    /// directory, environment, flags, presentable and client, each where
    /// this one names none.
    pub fn fill_from(&mut self, filled: &v1::Caller) {
        if self.cwd.is_empty() {
            self.cwd.clone_from(&filled.cwd);
        }
        if self.env.is_none() {
            self.env.clone_from(&filled.env);
        }
        if self.globals.is_none() {
            self.globals.clone_from(&filled.globals);
        }
        if self.presentable.is_none() {
            self.presentable.clone_from(&filled.presentable);
        }
        if self.client.is_none() {
            self.client.clone_from(&filled.client);
        }
    }
}

